
const visibilityComponentForm=componentForm;
function payoutDisplayKeys(c){const unit=state.units.find(u=>u.id===c.unit),tokens=String(c.formula||'').match(/[A-Za-z_]\w*/g)||[];return [...new Set([...(c.keys||[]),...sharedKeys.filter(k=>tokens.includes(k.formulaKey)||tokens.includes(k.id)).map(k=>k.id),...(c.basis==='Per Unit'&&c.lookup!=='Flat'?c.attrs.slice(0,c.lookup==='2D Lookup'?2:1):[]),...(c.unitFilterKey?[c.unitFilterKey]:[]),...(c.filters||[]).map(f=>f.key),...(unit?.attributes||[]).filter(a=>tokens.includes(a.name)).map(a=>a.name)])]}
function payoutNamingFields(c,i){return payoutDisplayKeys(c).map(k=>input('Display name · '+esc(displayKey(k)),`components.${i}.display.labels.${k}`,c.display?.labels?.[k]||displayKey(k).replaceAll('_',' '))).join('')}
componentForm=function(c,i){c.display||={};c.display.labels||={};return visibilityComponentForm(c,i).replace('</section>',`<div class="panel-body"><h3>Rider display</h3><label>Description<textarea data-k="components.${i}.description" rows="2">${esc(c.description||'')}</textarea></label><div class="grid section-gap">${select('Value display',`components.${i}.valueFormat`,[{id:'Amount',name:'Amount (₹)'},{id:'Percentage',name:'Percentage (%)'},{id:'Number',name:'Number'}],c.valueFormat||'Amount')}${input('Value label',`components.${i}.display.valueLabel`,c.display.valueLabel||'Value')}${c.basis==='Per Unit'?input('Unit count label',`components.${i}.display.unitsLabel`,c.display.unitsLabel||'Units')+input('Unit ID label',`components.${i}.display.unitIdLabel`,c.display.unitIdLabel||'Unit ID'):''}</div><div class="grid section-gap" id="payout-naming-${i}">${payoutNamingFields(c,i)}</div></div></section>`)};
for(const event of ['input','change'])document.addEventListener(event,e=>{if(editorType!=='structure'||!draft)return;const k=e.target.dataset.k||'';if(k.includes('.display.')||k.endsWith('.description'))return;for(const [i,c] of draft.components.entries()){const box=document.querySelector('#payout-naming-'+i);if(box)box.innerHTML=payoutNamingFields(c,i)}});
const visibilityStructureForm=structureForm;
structureForm=function(){visibilityStructureForm();const box=document.createElement('div');box.className='panel-body';box.id='cycle-settings';box.innerHTML=draft.period==='Monthly'?select('Monthly cycle starts on','cycleStart',Array.from({length:28},(_,i)=>({id:String(i+1),name:String(i+1)})),String(draft.cycleStart||1))+'<p class="quiet">Ends the day before the next monthly cycle starts.</p>':draft.period==='Weekly'?select('Week starts on','weekStart',['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],draft.weekStart||'Monday')+'<p class="quiet">Evaluates seven consecutive days.</p>':'';const periodField=document.querySelector('#editor [data-k="period"]');if(box.innerHTML&&periodField){const field=periodField.closest('label'),group=document.createElement('div');field.replaceWith(group);group.append(field,box);box.style.padding='12px 0 0';}};
document.addEventListener('change',e=>{if(editorType==='structure'&&e.target.dataset.k==='period')structureForm()});
if(!sharedKeys.some(k=>k.id==='attendance_hours'))sharedKeys.push({id:'attendance_hours',formulaKey:'attendance_hours',name:'Attendance hours',type:'Float'});
if(!state.visibilitySampleVersion){
 const make=(id,name,period,components,extra={})=>{const s={id,name,period,lob:'Last Mile',entity:'Rider',status:'Live',userType:'All',components,...extra};ensureOutputNames(s);state.structures.push(s);state.templates.push({id:'tpl-'+id,name:name+' · Sample',structure:id,components:clone(components),entityFilters:[]})};
 make('sample-month','Monthly base','Monthly',[comp('monthly_base','Monthly base','Fixed',{defaultValue:5000,keys:[],description:'A fixed amount for each completed monthly cycle.'})]);
 make('sample-week','Weekly allowance','Weekly',[comp('weekly_allowance','Weekly allowance','Fixed',{defaultValue:600,keys:['attendance_days'],filters:[{key:'attendance_days',op:'>=',value:5}],description:'Weekly allowance when at least five attendance days are recorded.'})],{weekStart:'Monday'});
 make('sample-day','Daily delivery payout','Daily',[
 comp('attendance','Attendance pay','Fixed',{defaultValue:500,keys:['attendance_hours'],filters:[{key:'attendance_hours',op:'>',value:5}],description:'Fixed daily pay when attendance exceeds five hours.'}),
 comp('delivery','Shipment pay','Per Unit',{lookup:'1D Lookup',attrs:['shipment_type'],rates:[{keys:['COD'],value:10},{keys:['Prepaid'],value:12},{keys:['BFSI'],value:14}],description:'Each delivered shipment earns the value listed for its shipment type.'}),
 comp('weight','Weight pay','Per Unit',{lookup:'2D Lookup',attrs:['shipment_type','weight_kg'],rates:['COD','Prepaid','BFSI'].flatMap(k=>[{keys:[k,{min:0,max:5}],value:2},{keys:[k,{min:5,max:'+'}],value:4}]),description:'An additional amount for each shipment, selected by shipment type and weight.'}),
 comp('daily_fee','Daily deduction','Fixed',{effect:'Deduct',defaultValue:10,formula:'running_payout * value / 100',keys:[],description:'Deduct 10% of the daily payout calculated before this component.'})]);
 state.visibilitySampleVersion=1;save();
}

const visibilitySyncDefinitions=syncTemplateDefinitions;
syncTemplateDefinitions=function(s){const previous=new Map(state.templates.filter(t=>t.structure===s.id).map(t=>[t.id,clone(t.components)]));visibilitySyncDefinitions(s);for(const t of state.templates.filter(t=>t.structure===s.id))for(const c of t.components){const old=previous.get(t.id)?.find(x=>x.id===c.id);if(c.basis==='Fixed'&&old){c.filters=(old.filters||[]).filter(f=>(c.keys||[]).includes(f.key));c.filterJoin=old.filterJoin||'AND';}}};

render();
